<?php
require_once __DIR__.'/../../auth_check.php';require_once __DIR__.'/../model/Database.php';$pdo=Database::getConnection();$number=trim((string)($_GET['num_fiche']??''));$type=(string)($_GET['type']??'');if(!in_array($type,['bci','fne','pv'],true)||$number===''){http_response_code(400);exit('Document invalide.');}$s=$pdo->prepare('SELECT num_fiche,created_by_user_id,feb_request_id,code_autorisation_feb,facture_reference,pv_reception_reference FROM fiche_decaissement WHERE num_fiche=:n LIMIT 1');$s->execute(['n'=>$number]);$fiche=$s->fetch(PDO::FETCH_ASSOC);if(!$fiche){http_response_code(404);exit('Fiche introuvable.');}$uid=(int)($_SESSION['user_id']??0);$allowed=$uid>0&&((int)$fiche['created_by_user_id']===$uid||AccessManager::hasPermission('acces_admin')||AccessManager::hasPermission('acces_achat')||AccessManager::hasPermission('acces_feb')||AccessManager::hasPermission('acces_finance'));if(!$allowed){http_response_code(403);exit('Accès refusé.');}
if($type==='bci'){$febId=(int)$fiche['feb_request_id'];if($febId<=0&&trim((string)$fiche['code_autorisation_feb'])!==''){$lookup=$pdo->prepare("SELECT id FROM employee_legal_requests WHERE request_type='feb' AND JSON_SEARCH(payload_json,'one',:code) IS NOT NULL ORDER BY (status='approved') DESC,id DESC LIMIT 1");$lookup->execute(['code'=>trim((string)$fiche['code_autorisation_feb'])]);$febId=(int)$lookup->fetchColumn();if($febId>0)$pdo->prepare('UPDATE fiche_decaissement SET feb_request_id=:feb WHERE num_fiche=:num AND feb_request_id IS NULL')->execute(['feb'=>$febId,'num'=>$number]);}if($febId<=0){http_response_code(404);exit('Aucune FEB correspondant au numéro BCI '.htmlspecialchars((string)$fiche['code_autorisation_feb']).' n’a été retrouvée.');}header('Location: ../../request/export_feb_pdf.php?id='.$febId);exit;}
$value=trim((string)$fiche[$type==='fne'?'facture_reference':'pv_reception_reference']);if($value===''){http_response_code(404);exit(strtoupper($type).' non joint.');}$candidates=preg_split('/[\r\n,;]+/',$value)?:[$value];$root=realpath(dirname(__DIR__,2));foreach($candidates as $candidate){$candidate=trim($candidate);if($candidate==='')continue;$relative=ltrim(preg_replace('~^(?:\.\./)+~','',$candidate),'/');$path=$root?realpath($root.'/'.$relative):false;if($path&&$root&&str_starts_with($path,$root.'/uploads/')&&is_file($path)){header('Content-Type: '.((new finfo(FILEINFO_MIME_TYPE))->file($path)?:'application/octet-stream'));header('Content-Disposition: inline; filename="'.basename($path).'"');header('X-Content-Type-Options: nosniff');readfile($path);exit;}}
?><!doctype html><html lang="fr"><meta charset="utf-8"><title><?=htmlspecialchars(strtoupper($type).' · '.$number)?></title><style>body{font-family:system-ui;background:#f1f5f9;margin:0;padding:32px;color:#0f172a}.card{max-width:780px;margin:auto;background:white;border-radius:24px;padding:28px;box-shadow:0 20px 50px #0f172a22}.badge{display:inline-block;background:#e0e7ff;color:#3730a3;padding:7px 12px;border-radius:999px;font-weight:800}pre{white-space:pre-wrap;background:#f8fafc;border:1px solid #e2e8f0;padding:18px;border-radius:14px}</style><div class="card"><span class="badge"><?=htmlspecialchars(strtoupper($type))?></span><h1><?=htmlspecialchars($number)?></h1><p>La pièce est enregistrée sous forme de référence documentaire.</p><pre><?=htmlspecialchars($value)?></pre></div></html>
